#include <api_caller_icons.h>

/** collection of all scene on_enter handlers */
static void (*const api_caller_scene_on_enter_handlers[])(void*) = {
    api_caller_scene_main_on_enter,
    api_caller_scene_wifi_on_enter,
    api_caller_scene_wifi_scan_on_enter,
    api_caller_scene_wifi_saved_on_enter,
    api_caller_scene_wifi_connect_on_enter,
    api_caller_scene_call_add_on_enter,
    api_caller_scene_call_list_on_enter,
    api_caller_scene_call_detail_on_enter,
};

/** collection of all scene on_event handlers */
static bool (*const api_caller_scene_on_event_handlers[])(void*, SceneManagerEvent) = {
    api_caller_scene_main_on_event,
    api_caller_scene_wifi_on_event,
    api_caller_scene_wifi_scan_on_event,
    api_caller_scene_wifi_saved_on_event,
    api_caller_scene_wifi_connect_on_event,
    api_caller_scene_call_add_on_event,
    api_caller_scene_call_list_on_event,
    api_caller_scene_call_detail_on_event,
};

/** collection of all scene on_exit handlers */
static void (*const api_caller_scene_on_exit_handlers[])(void*) = {
    api_caller_scene_main_on_exit,
    api_caller_scene_wifi_on_exit,
    api_caller_scene_wifi_scan_on_exit,
    api_caller_scene_wifi_saved_on_exit,
    api_caller_scene_wifi_connect_on_exit,
    api_caller_scene_call_add_on_exit,
    api_caller_scene_call_list_on_exit,
    api_caller_scene_call_detail_on_exit,
};

static const SceneManagerHandlers api_caller_scene_manager_handlers = {
    .on_enter_handlers = api_caller_scene_on_enter_handlers,
    .on_event_handlers = api_caller_scene_on_event_handlers,
    .on_exit_handlers = api_caller_scene_on_exit_handlers,
    .scene_num = ApiCallerSceneCount,
};

static bool api_caller_custom_event_callback(void* context, uint32_t event) {
    furi_assert(context);
    AppContext* app = context;
    return scene_manager_handle_custom_event(app->scene_manager, event);
}

static bool api_caller_navigation_event_callback(void* context) {
    furi_assert(context);
    AppContext* app = context;
    return scene_manager_handle_back_event(app->scene_manager);
}

static void api_caller_tick_event_callback(void* context) {
    furi_assert(context);
    AppContext* app = context;
    scene_manager_handle_tick_event(app->scene_manager);
}

static AppContext* api_caller_app_alloc(void) {
    AppContext* app = malloc(sizeof(AppContext));

    app->gui = furi_record_open(RECORD_GUI);

    app->view_dispatcher = view_dispatcher_alloc();
    view_dispatcher_attach_to_gui(app->view_dispatcher, app->gui, ViewDispatcherTypeFullscreen);

    app->scene_manager = scene_manager_alloc(&api_caller_scene_manager_handlers, app);

    view_dispatcher_set_event_callback_context(app->view_dispatcher, app);
    view_dispatcher_set_custom_event_callback(
        app->view_dispatcher, api_caller_custom_event_callback);
    view_dispatcher_set_navigation_event_callback(
        app->view_dispatcher, api_caller_navigation_event_callback);
    view_dispatcher_set_tick_event_callback(
        app->view_dispatcher, api_caller_tick_event_callback, 500);

    // Main menu view
    app->var_item_list = variable_item_list_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher,
        ApiCallerViewMainMenu,
        variable_item_list_get_view(app->var_item_list));

    // WiFi menu view
    app->var_item_list_wifi = variable_item_list_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher,
        ApiCallerViewWifiMenu,
        variable_item_list_get_view(app->var_item_list_wifi));

    // Call add/edit form view
    app->var_item_list_call = variable_item_list_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher,
        ApiCallerViewCallMenu,
        variable_item_list_get_view(app->var_item_list_call));

    // WiFi scan results view
    app->submenu = submenu_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher, ApiCallerViewWifiScan, submenu_get_view(app->submenu));

    // WiFi password input view
    app->text_input = text_input_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher, ApiCallerViewTextInput, text_input_get_view(app->text_input));

    // Shared TextBox used by stub scenes
    app->text_box = text_box_alloc();
    text_box_set_font(app->text_box, TextBoxFontText);
    view_dispatcher_add_view(
        app->view_dispatcher, ApiCallerViewTextBox, text_box_get_view(app->text_box));

    // WiFi state
    app->wifi_ssid_list = furi_string_alloc();
    app->fhttp = NULL;

    // Saved networks history
    app->wifi_history_count = 0;
    wifi_history_load(app);

    // Saved API calls
    app->call_edit_index = CALL_EDIT_INDEX_NONE;
    call_history_load(app);

    // Debug log (path resolved once)
    logger_init();
    logger_log("APP start");

    // FlipperHTTP link (fails gracefully if the board is not attached)
    wifi_manager_init(app);

    scene_manager_next_scene(app->scene_manager, ApiCallerSceneMain);

    return app;
}

static void api_caller_app_free(AppContext* app) {
    wifi_manager_deinit(app);

    view_dispatcher_remove_view(app->view_dispatcher, ApiCallerViewMainMenu);
    view_dispatcher_remove_view(app->view_dispatcher, ApiCallerViewWifiMenu);
    view_dispatcher_remove_view(app->view_dispatcher, ApiCallerViewCallMenu);
    view_dispatcher_remove_view(app->view_dispatcher, ApiCallerViewWifiScan);
    view_dispatcher_remove_view(app->view_dispatcher, ApiCallerViewTextInput);
    view_dispatcher_remove_view(app->view_dispatcher, ApiCallerViewTextBox);

    variable_item_list_free(app->var_item_list);
    variable_item_list_free(app->var_item_list_wifi);
    variable_item_list_free(app->var_item_list_call);
    submenu_free(app->submenu);
    text_input_free(app->text_input);
    text_box_free(app->text_box);

    furi_string_free(app->wifi_ssid_list);

    scene_manager_free(app->scene_manager);
    view_dispatcher_free(app->view_dispatcher);
    furi_record_close(RECORD_GUI);

    free(app);
}

int32_t api_caller(void* p) {
    UNUSED(p);

    AppContext* app = api_caller_app_alloc();
    view_dispatcher_run(app->view_dispatcher);
    api_caller_app_free(app);

    return 0;
}
